def write_files():
    for rel, content in FILES.items():
        dest = os.path.join(TARGET, *rel.split("/"))
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        with open(dest, "w", encoding="utf-8", newline="\n") as f:
            f.write(content)
        print("  wrote", rel)

def git_init():
    cmds = [
        ["git", "init"],
        ["git", "add", "."],
        ["git", "commit", "-m", "Launch author site"],
        ["git", "branch", "-M", "main"],
    ]
    for c in cmds:
        try:
            subprocess.run(c, cwd=TARGET, check=True)
        except (subprocess.CalledProcessError, FileNotFoundError) as e:
            print("  git step skipped:", " ".join(c), "->", e)
            return
    print("\nGit initialized. Now run, from", TARGET + ":")
    print("  git remote add origin https://github.com/arulanand/arulanand.github.io.git")
    print("  git push -u origin main")

if __name__ == "__main__":
    print("Creating site under", TARGET)
    os.makedirs(TARGET, exist_ok=True)
    write_files()
    print("\nFiles created.")
    ans = input("Initialize git now? [y/N] ").strip().lower()
    if ans == "y":
        git_init()
    else:
        print("Skipped git. Files are ready in", TARGET)
